#Region CallThisProcess
# A snippet of code provided as an example how to call this process should the developer be working on a system without access to an editor with auto-complete.
If( 1 = 0 );
    ExecuteProcess( '}bedrock.hier.clone', 'pLogOutput', pLogOutput,
      'pStrictErrorHandling', pStrictErrorHandling,
    	'pSourceDimension', '', 'pSourceHierarchy', '',
    	'pTargetDimension', '', 'pTargetHierarchy', '',
    	'pCreateMissingChildren', 0, 'pUnwind', 0
	);
EndIf;
#EndRegion CallThisProcess

#****Begin: Generated Statements***
#****End: Generated Statements****

################################################################################################### 
##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock-5 Ver 5.0~~## 
################################################################################################### 

#Region @DOC
# Description:
# This process will clone the source dimension Hierarchy.

# Use case: Mostly in Development.
# 1. Create a duplicate of an existing hierarchy for testing.

# Note:
# Valid source dimension name (pSourceDimension) and target dimension (pTargetDimension) names are mandatory otherwise the process will abort.
# Valid source hierarchy name (pSourceHierarchy) is mandatory otherwise the process will abort.

# Caution:
# - Target hierarchy cannot be `Leaves`.
# - If the target dimension Hierarchy exists then it will be overwritten.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sErrors         = '[]';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pSourceDimension":              null,
  "pSourceHierarchy":             null,
  "pTargetDimension":              "",
  "pTargetHierarchy":             "",
  "pFilter":              "",
  "pExcept":             "",
  "pCreateMissingChildren":                0,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0,
  "pUnwind":              0
}';

pPassedParameters = '{
  "pSourceDimension":              '|StringToJson  ( pSourceDimension              )|',
  "pSourceHierarchy":             '|StringToJson  ( pSourceHierarchy             )|',
  "pTargetDimension":              '|StringToJson  ( pTargetDimension              )|',
  "pTargetHierarchy":             '|StringToJson  ( pTargetHierarchy             )|',
  "pFilter":              '|StringToJson  ( pFilter              )|',
  "pExcept":              '|StringToJson  ( pExcept              )|',
  "pCreateMissingChildren":                '|NumberToString( pCreateMissingChildren                )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|',
  "pUnwind":              '|NumberToString( pUnwind              )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pSourceDimension              =                 JsonToString( JsonGet( pJson, 'pSourceDimension'              ) );
pSourceHierarchy             =                 JsonToString( JsonGet( pJson, 'pSourceHierarchy'             ) );
pTargetDimension              =                 JsonToString( JsonGet( pJson, 'pTargetDimension'              ) );
pTargetHierarchy             =                 JsonToString( JsonGet( pJson, 'pTargetHierarchy'             ) );
pFilter              =                 JsonToString( JsonGet( pJson, 'pFilter'              ) );
pExcept              =                 JsonToString( JsonGet( pJson, 'pExcept'              ) );
# Numeric Parameters
pCreateMissingChildren                = StringToNumber( JsonToString( JsonGet( pJson, 'pCreateMissingChildren'                ) ) );
pLogOutput           = StringToNumber( JsonToString( JsonGet( pJson, 'pLogOutput'           ) ) );
pStrictErrorHandling = StringToNumber( JsonToString( JsonGet( pJson, 'pStrictErrorHandling' ) ) );
pUnwind              = StringToNumber( JsonToString( JsonGet( pJson, 'pUnwind'              ) ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
sMessages = JsonAdd( sMessages, '/Info/-', pJson );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0', 0, ' ' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

### Validate Parameters ###
nErrors = 0;

If( Scan( ':', pSourceDimension ) > 0 & pSourceHierarchy @= '' );
    # A hierarchy has been passed as dimension. Handle the input error by splitting dim:hier into dimension & hierarchy
    pSourceHierarchy       = SubSt( pSourceDimension, Scan( ':', pSourceDimension ) + 1, Long( pSourceDimension ) );
    pSourceDimension        = SubSt( pSourceDimension, 1, Scan( ':', pSourceDimension ) - 1 );
EndIf;

## Validate Source dimension
IF( Trim( pSourceDimension ) @= '' );
    nErrors = 1;
    sMessage = 'No source dimension specified.';
    LogOutput( 'INFO', sMessage );
EndIf;

IF( DimensionExists( pSourceDimension ) = 0 );
    nErrors = 1;
    sMessage = 'Invalid source dimension: ' | pSourceDimension;
    LogOutput( 'INFO', sMessage );
EndIf;

# Validate Source hierarchy
IF( Trim( pSourceHierarchy ) @= '' );
    pSourceHierarchy = pSourceDimension;
ElseIF(HierarchyExists(pSourceDimension,pSourceHierarchy ) = 0 );
    nErrors = 1;
    sMessage = 'Invalid source hierarchy: ' | pSourceHierarchy;
    LogOutput( 'INFO', sMessage );
EndIf;

# Validate Target dimension
IF( Trim( pTargetDimension ) @= '' );
  pTargetDimension = pSourceDimension;
ElseIf( Scan( ':', pTargetDimension ) > 0 & pTargetHierarchy @= '' );
    # A hierarchy has been passed as dimension. Handle the input error by splitting dim:hier into dimension & hierarchy
    pTargetHierarchy       = SubSt( pTargetDimension, Scan( ':', pTargetDimension ) + 1, Long( pTargetDimension ) );
    pTargetDimension        = SubSt( pTargetDimension, 1, Scan( ':', pTargetDimension ) - 1 );
EndIf;

# Validate target hierarchy
If(pTargetHierarchy @= '');
  pTargetHierarchy = pSourceDimension;
Endif;

IF(pTargetHierarchy @= 'Leaves' );
  nErrors = 1;
  sMessage = 'Leaves is an invalid selection for Target Hierarchy: ' | pTargetDimension |':'|pTargetHierarchy;
    LogOutput( 'INFO', sMessage );
EndIf;

### Check for errors before continuing
If( nErrors <> 0 );
  If( pStrictErrorHandling = 1 ); 
      ProcessQuit; 
  Else;
      ProcessBreak;
  EndIf;
EndIf;

If( pFilter @= '' );
  pFilter = StringToJson( '{TM1SUBSETALL(['|pSourceDimension|'].['|pSourceHierarchy|'])}' );
Endif;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Create Subset Datasouce


# Create target Dimension and Hierarchy
If ( DimensionExists( pTargetDimension ) = 0 );
  DimensionCreate( pTargetDimension );
EndIf;
If( HierarchyExists( pTargetDimension, pTargetHierarchy) = 0 );
    HierarchyCreate( pTargetDimension, pTargetHierarchy );
Else;
#    IF(pUnwind = 1 );
#      nRet = ExecuteProcess('}bedrock.hier.unwind',
#        'pLogOutput', pLogOutput,
#        'pStrictErrorHandling', pStrictErrorHandling,
#        'pDim', pTargetDimension,
#        'pHier', pTargetHierarchy,
#        'pConsol', '*',
#        'pRecursive', 1
#        );
#    ELSEIF(pUnwind = 2 );
#      #Do nothing
#    ELSEIF(pUnwind = 0 );
#      HierarchyDeleteAllElements( pTargetDimension, pTargetHierarchy );
#    EndIf;
EndIf;
  
# Create subset to process
ExecuteProcess('}bedrock.hier.sub.create.from_json',
  'pDimension', pSourceDimension,
  'pHierarchy', pSourceHierarchy,
  'pSubset', cTemp,
  'pFilter', pFilter,
  'pExcept', pExcept );

# Assign Data Source
DatasourceNameForServer     = pSourceDimension|':'|pSourceHierarchy;
DataSourceType              = 'SUBSET';
DatasourceDimensionSubset   = cTemp;

nCount = HierarchySubsetGetSize( pSourceDimension, pSourceHierarchy, cTemp );

#EndRegion - Create Subset Datasouce
#################################################################################################

MetadataProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

sElementType = ElementType( pSourceDimension, pSourceHierarchy, vElement );
IF( sElementType @<> 'C' );
  ITEMSKIP;
ENDIF;

IF( HierarchyElementExists( pTargetDimension, pTargetHierarchy, vElement ) = 0 );
  IF( pCreateMissingParents = 1 );
    HierarchyElementInsert( pTargetDimension, pTargetHierarchy, '', vElement, 'C' );
  ELSE;
    ITEMSKIP;
  ENDIF;
ENDIF;

nCount = ElementComponentCount( pSourceDimension, pSourceHierarchy, vElement );
WHILE( nCount > 0 );
  sComponentElement = ElementComponent( pSourceDimension, pSourceHierarchy, vElement, nCount );
  
  IF( HierarchyElementExists( pTargetDimension, pTargetHierarchy, sComponentElement ) = 0 & pCreateMissingChildren = 1 );
    IF( pCreateUnspecifiedElements = 1 % HierarchySubsetElementExists( pSourceDimension, pSourceHierarchy, cTemp, sComponentElement ) = 1 );
      sComponentElementType = ElementType( pSourceDimension, pSourceHierarchy, sComponentElement );
      HierarchyElementInsert( pTargetDimension, pTargetHierarchy, '', sComponentElement, sComponentElementType );
    ENDIF;
  ENDIF;
  
  IF( HierarchyElementExists( pTargetDimension, pTargetHierarchy, sComponentElement ) = 1 );
    nWeight = ElementWeight( pSourceDimension, pSourceHierarchy, vElement, sComponentElement );
    HierarchyElementComponentAdd( pTargetDimension, pTargetHierarchy, vElement, sComponentElement, nWeight );
  ENDIF;
  
  nCount = nCount - 1;
END;

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****
  
### Return code & final error message handling
If( nErrors > 0 );
    sMessage = 'the process incurred at least 1 error. Please see above lines in this file for more details.';
    nProcessReturnCode = 0;
    LogOutput( 'INFO', sMessage );
    sProcessReturnCode = Expand( '%sProcessReturnCode% Process:%cThisProcName% completed with errors. Check tm1server.log for details.' );
    If( pStrictErrorHandling = 1 ); 
        ProcessQuit; 
    EndIf;
Else;
    sProcessAction = Expand( 'Process:%cThisProcName% successfully cloned the %pSourceDimension%:%pSourceHierarchy% dimension:hierarchy to %pTargetDimension%:%pTargetHierarchy%' );
    sProcessReturnCode = Expand( '%sProcessReturnCode% %sProcessAction%' );
    nProcessReturnCode = 1;
    If( pLogoutput = 1 );
        LogOutput('INFO', Expand( sProcessAction ) );   
    EndIf;
EndIf;
